<?php

namespace models\communication;

use core\Model;
use Database;
use models\acteurs\Personne;

/**
 * Modèle d'association liant un gabarit d'e-mail à un destinataire (table TD_DESTINER).
 *
 * @author  AutoGenerated / POO Refactor
 * @version 1.0
 */
class Destiner extends Model
{
    public string $TEM_NUM;
    public string $PER_ID;

    /**
     * Instancie et hydrate le modèle à partir d'un tableau associatif.
     *
     * @param array<string, mixed> $data
     * @return static
     */
    public static function fromArray(array $data): static
    {
        return (new static())->hydrate($data);
    }

    /**
     * Recherche un enregistrement par sa clé composite (TEM_NUM, PER_ID).
     *
     * @param string $tem_num
     * @param string $per_id
     * @return static|null
     */
    public static function find(string $tem_num, string $per_id): ?static
    {
        $stmt = Database::getInstance()->prepare('SELECT * FROM TD_DESTINER WHERE TEM_NUM = ? AND PER_ID = ? LIMIT 1');
        $stmt->execute([$tem_num, $per_id]);
        $row = $stmt->fetch();

        return $row ? (new static())->hydrate($row) : null;
    }

    /**
     * Récupère tous les enregistrements de la table.
     *
     * @return static[]
     */
    public static function findAll(): array
    {
        $stmt = Database::getInstance()->query('SELECT * FROM TD_DESTINER');
        $rows = $stmt->fetchAll();

        return array_map(fn($row) => (new static())->hydrate($row), $rows);
    }

    /**
     * Récupère les instances Destiner associées à un objet TemplateMail.
     *
     * @param TemplateMail $source
     * @return static[]
     */
    public static function getFromTemplateMail(TemplateMail $source): array
    {
        $stmt = Database::getInstance()->prepare('SELECT * FROM TD_DESTINER WHERE TEM_NUM = ?');
        $stmt->execute([$source->TEM_NUM]);
        $rows = $stmt->fetchAll();

        return array_map(fn($row) => (new static())->hydrate($row), $rows);
    }

    /**
     * Navigue vers l'objet TemplateMail parent lié à cet enregistrement.
     *
     * @return TemplateMail|null
     */
    public function getTemplateMail(): ?TemplateMail
    {
        if (!isset($this->TEM_NUM)) {
            return null;
        }
        return TemplateMail::findById($this->TEM_NUM);
    }

    /**
     * Récupère les instances Destiner associées à un objet Personne.
     *
     * @param Personne $source
     * @return static[]
     */
    public static function getFromPersonne(Personne $source): array
    {
        $stmt = Database::getInstance()->prepare('SELECT * FROM TD_DESTINER WHERE PER_ID = ?');
        $stmt->execute([$source->PER_ID]);
        $rows = $stmt->fetchAll();

        return array_map(fn($row) => (new static())->hydrate($row), $rows);
    }

    /**
     * Navigue vers l'objet Personne parent lié à cet enregistrement.
     *
     * @return Personne|null
     */
    public function getPersonne(): ?Personne
    {
        if (!isset($this->PER_ID)) {
            return null;
        }
        return Personne::findById($this->PER_ID);
    }

}

if (!class_exists('models\Destiner', false)) {
    class_alias(Destiner::class, 'models\Destiner');
}
